async run(input: AcousticInferenceInput): Promise<AcousticInferenceResult> {
    if (this.state !== 'READY' || this.busy) throw new AcousticAnalysisError('ACOUSTIC_WORKER_CONCURRENCY_OR_STATE');
    this.busy = true;
    try { return await this.send({ type: 'INFER', input }) as AcousticInferenceResult; }
    catch (error) { this.terminate(); throw error; }
    finally { this.busy = false; }
  }

async dispose(): Promise<void> {
    if (this.state === 'CLOSED') return;
    if (this.busy) { this.terminate('ACOUSTIC_WORKER_DISPOSED'); return; }
    try { await this.send({ type: 'DISPOSE' }); } finally { this.terminate(); }
  }

terminate(code = 'ACOUSTIC_WORKER_TERMINATED'): void {
    if (this.state === 'CLOSED') return;
    this.state = 'CLOSED';
    const error = new AcousticAnalysisError(code);
    for (const pending of this.pending.values()) pending.reject(error);
    this.pending.clear(); this.worker.terminate();
    if (code !== 'ACOUSTIC_WORKER_TERMINATED' && code !== 'ACOUSTIC_WORKER_DISPOSED') this.failureListener?.(error);
  }

async run(input: AcousticInferenceInput): Promise<AcousticInferenceResult> {
    onlyFields(input, ['window', 'pcm']);
    onlyFields(input.window, ['jobIndex', 'regionIndex', 'windowIndex', 'ownedStartTarget', 'ownedEndTarget', 'startSample', 'endSample']);
    if (this.busy) fail('ACOUSTIC_WORKER_CONCURRENCY_REJECTED');
    if (this.state !== 'READY' || !this.session) fail('ACOUSTIC_WORKER_NOT_READY');
    const w = input.window;
    assertWindowGeometry(w);
    if (w.jobIndex !== this.nextJob || !(input.pcm instanceof Float32Array) || input.pcm.length !== M.inputSamples
      || input.pcm.some(v => !Number.isFinite(v))) fail('ACOUSTIC_WORKER_WINDOW_MISMATCH');
    this.busy = true;
    try {
      const started = performance.now();
      const audio = new ort.Tensor('float32', input.pcm, [1, 29120]);
      let tensors: ort.InferenceSession.OnnxValueMapType | undefined;
      let raw: PianoRawOutputs;
      try {
        this.runs++;
        tensors = await this.session.run({ audio }, ['reg_onset_output', 'frame_output']);
        raw = { reg_onset_output: outputData(tensors.reg_onset_output), reg_onset_shape: [1, 183, 88],
          frame_output: outputData(tensors.frame_output), frame_shape: [1, 183, 88] };
      } finally { audio.dispose(); for (const tensor of Object.values(tensors ?? {})) tensor.dispose(); }
      const inferred = performance.now(), events = decodeAcousticOutputs(raw, input), decoded = performance.now();
      this.nextJob++;
      return { events, inferenceMs: inferred - started, decodeMs: decoded - inferred, actualSessionRunCount: this.runs };
    } catch (error) { this.state = 'FAILED'; throw error; }
    finally { this.busy = false; }
  }

async dispose(): Promise<void> {
    if (this.delivering) fail('ACOUSTIC_PUBLICATION_REENTRANCY');
    if (this.state === 'DISPOSED') return;
    this.state = 'DISPOSED'; this.regions.length = 0; this.active = null;
    this.cleanup?.(); this.cleanup = null; this.detachWorker?.(); this.detachWorker = undefined;
    await this.options.worker.dispose(); await this.chain;
  }

private enqueue(window: AcousticWindow, pcm: Float32Array): void {
    const queued = this.clock(), depth = ++this.outstanding;
    this.queuedRegions.set(window.regionIndex, (this.queuedRegions.get(window.regionIndex) ?? 0) + 1);
    this.counts.windowsQueued++; this.counts.peakOutstanding = Math.max(this.counts.peakOutstanding, depth);
    this.chain = this.chain.then(async () => {
      try {
        if (this.closed()) return;
        const started = this.clock(); this.counts.windowsStarted++;
        const result = await this.options.worker.run({ window, pcm }); if (this.closed()) return;
        const available = this.clock(), publication = sourcePublication(this.options.sourceDomainId, this.adapter.rate, this.base!, window, result, available);
        this.delivering = true;
        try { deliverSynchronously(this.options.onPublication, publication); } finally { this.delivering = false; }
        const delivered = this.clock(); this.counts.windowsPublished++; this.counts.observationsPublished += publication.observations.length;
        retainCompact(this.diagnostics, Object.freeze({ jobIndex: window.jobIndex, regionIndex: window.regionIndex,
          ownedStartTarget: window.ownedStartTarget, ownedEndTarget: window.ownedEndTarget, inputStartSample: window.startSample,
          inputEndSample: window.endSample, queueDelayMs: started - queued, inferenceMs: result.inferenceMs, decodeMs: result.decodeMs,
          publicationMs: delivered - available, eventCount: publication.observations.length, outstandingAtEnqueue: depth, actualSessionRunCount: result.actualSessionRunCount }));
      } catch (error) { this.failAnalysis(error); } finally {
        this.outstanding--;
        const remaining = this.queuedRegions.get(window.regionIndex)! - 1;
        if (remaining) this.queuedRegions.set(window.regionIndex, remaining); else this.queuedRegions.delete(window.regionIndex);
      }
    });
  }

